WITH cleaned AS (SELECT id, customer_id, device, started_at, country, LENGTH(device) device_length FROM sessions WHERE started_at >= DATE '2023-10-09' AND browser = 'Edge'), with_gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM cleaned), sessions_sessions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps), metrics AS (SELECT *, LAG(is_new_burst, 2) OVER (PARTITION BY country ORDER BY started_at, id) prev_is_new_burst, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at DESC, id) row_seq, PERCENT_RANK() OVER (PARTITION BY country, customer_id ORDER BY is_new_burst DESC) is_new_burst_percent_rank FROM sessions_sessions), eligible AS (SELECT s.* FROM metrics s WHERE EXISTS (SELECT 1 FROM web_events c WHERE c.session_id = s.id AND c.page IS NOT NULL)) SELECT burst_id, APPROX_PERCENTILE(burst_id, ARRAY(0.25, 0.5, 0.75)) AS burst_id_quartiles, ROUND(AVG(is_new_burst), 2) AS avg_is_new_burst, MAX(started_at) AS last_started_at FROM eligible GROUP BY burst_id HAVING avg_is_new_burst < 0 ORDER BY burst_id DESC NULLS LAST;
